<?php
/**
 * Shared helpers for the booking and address scripts.
 *
 * Settings: public ones come from config.php (generated by build.mjs). Private ones (the booking
 * email, the Google key, SMTP login) are copied the first time they are seen into a settings file
 * one folder above public_html, so a later redeploy without them doesn't switch emails off.
 */
declare(strict_types=1);

const CLEARLOT_PRIVATE_KEYS = ['bookingEmail', 'fromEmail', 'googleMapsApiKey', 'smtpHost', 'smtpPort', 'smtpUser', 'smtpPass', 'smtpSecure'];

function clearlot_data_dir(): string
{
    static $dir = null;
    if ($dir !== null) return $dir;
    $dir = dirname(__DIR__, 2) . '/clearlot-bookings';
    if (!is_dir($dir) && !@mkdir($dir, 0750, true)) {
        $dir = __DIR__ . '/data';
        if (!is_dir($dir)) @mkdir($dir, 0750, true);
        if (!file_exists($dir . '/.htaccess')) @file_put_contents($dir . '/.htaccess', "Require all denied\nDeny from all\n");
    }
    return $dir;
}

function clearlot_settings(): array
{
    static $s = null;
    if ($s !== null) return $s;
    $s = require __DIR__ . '/config.php';
    $file = clearlot_data_dir() . '/settings.json';
    $saved = is_file($file) ? (json_decode((string) file_get_contents($file), true) ?: []) : [];
    $fresh = [];
    foreach (CLEARLOT_PRIVATE_KEYS as $k) {
        if (isset($s[$k]) && $s[$k] !== '') $fresh[$k] = (string) $s[$k];
    }
    $merged = $fresh + $saved;
    if ($merged != $saved) {
        @file_put_contents($file, json_encode($merged), LOCK_EX);
        @chmod($file, 0600);
    }
    foreach (CLEARLOT_PRIVATE_KEYS as $k) {
        if (($s[$k] ?? '') === '' && isset($saved[$k])) $s[$k] = $saved[$k];
        $s[$k] = (string) ($s[$k] ?? '');
    }
    return $s;
}

/** Simple per-visitor limit, stored as timestamps in a small file. */
function clearlot_rate_ok(string $bucket, int $max, int $windowSeconds): bool
{
    $ip = $_SERVER['REMOTE_ADDR'] ?? 'unknown';
    $file = clearlot_data_dir() . '/rate-' . $bucket . '-' . substr(hash('sha256', $ip), 0, 16) . '.txt';
    $now = time();
    $recent = array_filter(array_map('intval', @file($file, FILE_IGNORE_NEW_LINES) ?: []), fn ($t) => $t > $now - $windowSeconds);
    if (count($recent) >= $max) return false;
    $recent[] = $now;
    @file_put_contents($file, implode("\n", $recent), LOCK_EX);
    return true;
}

function clearlot_header_safe(string $s): string
{
    return trim(str_replace(["\r", "\n"], '', $s));
}

/** The address emails come from: the SMTP login, or bookings@ this website's domain. */
function clearlot_from(array $s): string
{
    if ($s['fromEmail'] !== '') return $s['fromEmail'];
    if ($s['smtpUser'] !== '' && filter_var($s['smtpUser'], FILTER_VALIDATE_EMAIL)) return $s['smtpUser'];
    $host = preg_replace('/^www\./', '', strtolower((string) ($_SERVER['HTTP_HOST'] ?? 'localhost')));
    $host = preg_replace('/[^a-z0-9.-]/', '', (string) $host);
    return 'bookings@' . ($host !== '' ? $host : 'localhost');
}

/** Sends a plain-text email. Uses SMTP when it is set up, otherwise the server's mail(). */
function clearlot_send(array $s, string $to, string $subject, string $body, string $replyTo = ''): bool
{
    $from = clearlot_header_safe(clearlot_from($s));
    $to = clearlot_header_safe($to);
    if (!filter_var($to, FILTER_VALIDATE_EMAIL) || !filter_var($from, FILTER_VALIDATE_EMAIL)) return false;
    $name = clearlot_header_safe($s['siteName']);
    $encodedSubject = '=?UTF-8?B?' . base64_encode(clearlot_header_safe($subject)) . '?=';
    $encodedName = '=?UTF-8?B?' . base64_encode($name) . '?=';
    $headers = [
        'From: ' . $encodedName . ' <' . $from . '>',
        'MIME-Version: 1.0',
        'Content-Type: text/plain; charset=UTF-8',
        'Content-Transfer-Encoding: 8bit',
    ];
    if ($replyTo !== '' && filter_var($replyTo, FILTER_VALIDATE_EMAIL)) $headers[] = 'Reply-To: ' . clearlot_header_safe($replyTo);
    $body = str_replace(["\r\n", "\r"], "\n", $body);

    if ($s['smtpHost'] !== '') {
        return clearlot_smtp($s, $from, $to, $encodedSubject, $headers, $body);
    }
    return @mail($to, $encodedSubject, $body, implode("\r\n", $headers), '-f' . $from);
}

/** A small SMTP client: SSL (port 465), STARTTLS (587) or plain, with AUTH LOGIN. */
function clearlot_smtp(array $s, string $from, string $to, string $subject, array $headers, string $body): bool
{
    $port = (int) ($s['smtpPort'] !== '' ? $s['smtpPort'] : 465);
    $secure = $s['smtpSecure'] !== '' ? $s['smtpSecure'] : ($port === 465 ? 'ssl' : 'tls');
    $fp = @stream_socket_client(($secure === 'ssl' ? 'ssl://' : 'tcp://') . $s['smtpHost'] . ':' . $port, $errno, $errstr, 15);
    if (!$fp) {
        error_log("clearlot smtp connect failed: $errstr");
        return false;
    }
    stream_set_timeout($fp, 20);
    $read = function () use ($fp): int {
        $code = 0;
        while (($line = fgets($fp, 1024)) !== false) {
            $code = (int) substr($line, 0, 3);
            if (strlen($line) < 4 || $line[3] === ' ') break;
        }
        return $code;
    };
    $say = function (?string $line, array $ok) use ($fp, $read): bool {
        if ($line !== null) fwrite($fp, $line . "\r\n");
        $code = $read();
        if (!in_array($code, $ok, true)) {
            error_log('clearlot smtp: unexpected ' . $code . ' after ' . ($line === null ? 'connect' : strtok($line, ' ')));
            return false;
        }
        return true;
    };
    $helo = 'EHLO ' . (preg_replace('/[^a-z0-9.-]/i', '', (string) gethostname()) ?: 'localhost');
    $ok = $say(null, [220]) && $say($helo, [250]);
    if ($ok && $secure === 'tls') {
        $ok = $say('STARTTLS', [220]) && stream_socket_enable_crypto($fp, true, STREAM_CRYPTO_METHOD_TLS_CLIENT) && $say($helo, [250]);
    }
    if ($ok && $s['smtpUser'] !== '') {
        $ok = $say('AUTH LOGIN', [334]) && $say(base64_encode($s['smtpUser']), [334]) && $say(base64_encode($s['smtpPass']), [235]);
    }
    $ok = $ok && $say("MAIL FROM:<$from>", [250]) && $say("RCPT TO:<$to>", [250, 251]) && $say('DATA', [354]);
    if ($ok) {
        $msg = array_merge(
            ['Date: ' . date('r'), 'To: <' . $to . '>', 'Subject: ' . $subject, 'Message-ID: <' . bin2hex(random_bytes(12)) . '@' . substr(strrchr($from, '@'), 1) . '>'],
            $headers,
        );
        $text = implode("\r\n", $msg) . "\r\n\r\n" . str_replace("\n", "\r\n", $body);
        $text = preg_replace('/^\./m', '..', $text); // dot-stuffing
        $ok = $say($text . "\r\n.", [250]);
    }
    @fwrite($fp, "QUIT\r\n");
    fclose($fp);
    return $ok;
}
